<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('attendance.view_own');verify_csrf();$pdo=staff_db();$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'&&can('attendance.clock')){$a=$_POST['action']??'';if($a==='clock_in'){$late='09:15:00';$setting=$pdo->query("SELECT setting_value FROM system_settings WHERE setting_key='attendance_late_after'")->fetchColumn();if($setting)$late=$setting;$status=date('H:i:s')>$late?'late':'present';$pdo->prepare("INSERT INTO attendance(staff_id,attendance_date,clock_in,status) VALUES(?,CURDATE(),NOW(),?) ON DUPLICATE KEY UPDATE clock_in=COALESCE(clock_in,NOW())")->execute([$staff['id'],$status]);}elseif($a==='clock_out'){$pdo->prepare("UPDATE attendance SET clock_out=NOW() WHERE staff_id=? AND attendance_date=CURDATE()")->execute([$staff['id']]);}staff_redirect('staff/pages/attendance.php');}
$s=$pdo->prepare("SELECT * FROM attendance WHERE staff_id=? ORDER BY attendance_date DESC LIMIT 40");$s->execute([$staff['id']]);$rows=$s->fetchAll();$today=null;foreach($rows as $r){if($r['attendance_date']===date('Y-m-d')){$today=$r;break;}}
$pageTitle='Attendance';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Timekeeping</p><h1>Attendance</h1></div><form method="post"><?= csrf_field() ?><?php if(!$today||!$today['clock_in']):?><button class="btn primary" name="action" value="clock_in">Clock in</button><?php elseif(!$today['clock_out']):?><button class="btn primary" name="action" value="clock_out">Clock out</button><?php else:?><span class="badge">Completed today</span><?php endif;?></form></div><section class="staff-panel table-panel"><table><thead><tr><th>Date</th><th>Clock in</th><th>Clock out</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h(date('j M Y',strtotime($r['attendance_date']))) ?></td><td><?= $r['clock_in']?h(date('g:i A',strtotime($r['clock_in']))):'—' ?></td><td><?= $r['clock_out']?h(date('g:i A',strtotime($r['clock_out']))):'—' ?></td><td><span class="pill"><?= h($r['status']) ?></span></td><td><?= h($r['notes']?:'—') ?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
